    fn from(value: AnimatePacketView) -> Self {
        let _ = &value;
        Self {
            action: value.action,
            target_actor_runtime_id: (value.target_actor_runtime_id).into(),
            data: value.data,
            swing_source: (value.swing_source)
                .map(|value| crate::bedrock::codec::decode_utf8_lossy_bytes((value).into_bytes())),
        }
    }
